"""Generate the vector table source of an STM32 device (src/init/vectors_<device>.c).

The list of interrupts of a device is taken from the start-up file which STMicroelectronics publishes with the
CMSIS device package (cmsis_device_xx/Source/Templates/gcc/startup_<device>.s, see deps/scripts/deps.py). Only the
order and the names of the handlers are read from it, the generated code is the STK one.

Usage:
    gen_vectors.py <startup_device.s> [-o vectors_device.c]

Example (add STM32F411xE):
    python3 deps/scripts/fetch_deps.py stm32-f4
    python3 gen_vectors.py ../../../stm32/f4/cmsis-device/Source/Templates/gcc/startup_stm32f411xe.s \
            -o ../src/init/vectors_stm32f411xe.c

The device header is included by the generated file, so the handler names which it renames (for example
RCC_CRS_IRQHandler -> RCC_IRQHandler of STM32F0, FMC_IRQHandler -> FSMC_IRQHandler of STM32F407) are the ones of
the CMSIS device package.

Handlers of the core exceptions (NMI, HardFault, SVC, ...) are implemented in exceptions.c, all other handlers are
emitted as weak aliases of Default_Handler, which the application overrides by defining a function of the same name.
"""

import argparse
import re
import sys
from pathlib import Path

CORE_HANDLERS = {
    "NMI_Handler", "HardFault_Handler", "MemManage_Handler", "BusFault_Handler", "UsageFault_Handler",
    "SVC_Handler", "DebugMon_Handler", "PendSV_Handler", "SysTick_Handler",
}

HEADER = """\
/*
 * SuperTinyKernel(TM) RTOS: Lightweight High-Performance Deterministic C++ RTOS for Embedded Systems.
 *
 * Source: https://github.com/SuperTinyKernel-RTOS
 *
 * Copyright (c) 2022-2026 Neutron Code Limited <stk@neutroncode.com>. All Rights Reserved.
 * License: MIT License, see LICENSE for a full text.
 */

/*! \\file  {fname}
    \\brief Vector table generated by tools/gen_vectors.py from {startup} (do not edit by hand).
    \\see   exceptions.h, sections.ld (section \\c .isr_vector)
*/

#include "cmsis_device.h"
#include "exceptions.h"

"""


def parse_vectors(text: str) -> list[str]:
    """Return the entries of g_pfnVectors in order: handler name, or '0' for a reserved slot."""
    m = re.search(r"^g_pfnVectors:\s*$", text, re.M)
    if not m:
        raise ValueError("g_pfnVectors table not found")

    entries: list[str] = []
    for line in text[m.end():].splitlines():
        line = re.sub(r"/\*.*?\*/", "", line).split("@")[0].strip()
        if not line:
            continue
        w = re.match(r"\.word\s+(\S+)", line)
        if not w:
            break  # the table ends with the first line which is not a .word
        entries.append(w.group(1))
    return entries


def generate(entries: list[str], startup: str, fname: str) -> str:
    if len(entries) < 16 or entries[0] != "_estack" or entries[1] != "Reset_Handler":
        raise ValueError("unexpected vector table layout")

    # BootRAM is a constant (boot-from-RAM marker of STM32F10x medium density), not a handler
    entries = [e for e in entries if e != "BootRAM"]

    irqs = [e for e in entries[16:] if re.fullmatch(r"[A-Za-z_]\w*", e) and e != "0"]
    unknown = [e for e in entries[2:] if e != "0" and not re.fullmatch(r"[A-Za-z_]\w*", e)]
    if unknown:
        raise ValueError(f"unsupported vector entries: {unknown}")

    out = [HEADER.format(fname=fname, startup=startup)]

    out.append("""\
/*! \\brief Processor ends up here if an interrupt occurs and the application has not defined its handler.
    \\note  In a DEBUG build the debugger is notified, then the CPU stops in a busy loop.
*/
void Default_Handler(void) __attribute__ ((weak, used));

void Default_Handler(void)
{
#if defined(DEBUG)
    __asm volatile ("bkpt 0");
#endif
    for (;;)
    {
        // nothing to do
    }
}

/*! \\name Device interrupt handlers.
    \\note Weak, aliased to Default_Handler: a function of the same name in the application overrides it.
*/
""")
    seen = set()
    for name in irqs:
        if name in seen:
            continue
        seen.add(name)
        out.append(f"void {name}(void) __attribute__ ((weak, alias(\"Default_Handler\")));\n")

    out.append("""
/*! \\brief Vector table, placed at the beginning of the flash memory by the linker script.
    \\note  Entry 0 is the initial stack pointer, entries 1..15 are the core exceptions, from entry 16 the device
            interrupts (IRQ number + 16). Zero entries are reserved slots.
*/
__attribute__ ((section(".isr_vector"), used))
const IsrVector_t __isr_vectors[] =
{
""")
    for i, name in enumerate(entries):
        if name == "_estack":
            val, note = "{ .stack = &_estack }", "initial stack pointer"
        elif name == "0":
            val, note = "{ 0 }", "reserved"
        else:
            val, note = f"{{ .isr = {name} }}", ("exception" if i < 16 else f"IRQ{i - 16}")
        out.append(f"    {val + ',':<34} // {i:3d} {note}\n")
    out.append("};\n")
    return "".join(out)


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("startup", type=Path, help="startup_<device>.s from the CMSIS device package of STMicroelectronics")
    ap.add_argument("-o", "--output", type=Path, help="output file (default: stdout)")
    args = ap.parse_args()

    device = args.startup.stem.removeprefix("startup_")
    fname = args.output.name if args.output else f"vectors_{device}.c"
    try:
        code = generate(parse_vectors(args.startup.read_text(encoding="utf-8", errors="replace")),
                        args.startup.name, fname)
    except (OSError, ValueError) as e:
        print(f"gen_vectors: {e}", file=sys.stderr)
        return 1

    if args.output:
        args.output.write_text(code, encoding="utf-8", newline="\n")
    else:
        sys.stdout.write(code)
    return 0


if __name__ == "__main__":
    sys.exit(main())
